type Recovery = 'retry' | 'fallback' | 'escalate' | 'abort';

async function withRecovery<T>(
  op: () => Promise<T>,
  classify: (e: unknown) => Recovery,
  fallback?: () => Promise<T>
): Promise<T> {
  for (let attempt = 0; attempt < 3; attempt++) {
    try { return await op(); }
    catch (e) {
      const r = classify(e);
      if (r === 'retry') await sleep(2 ** attempt * 100);
      else if (r === 'fallback' && fallback) return fallback();
      else if (r === 'escalate') throw new HumanEscalation(e);
      else throw e;
    }
  }
  throw new Error('exhausted retries');
}
